/**
 * dither-core: the shared engine behind every dithercn component.
 * Import from `@/lib/dither`.
 */

export {
  BAYER_2,
  BAYER_4,
  BAYER_8,
  BLUE_NOISE_64,
  DITHER_MATRICES,
  getThresholdMap,
  isInked,
  thresholdAt,
} from "@/lib/dither/matrices";
export type { DitherMatrix, ThresholdMap } from "@/lib/dither/matrices";

export {
  cssColor,
  DEFAULT_PALETTE,
  DITHER_COLOR_NAMES,
  DITHER_COLORS,
  MOTION,
} from "@/lib/dither/tokens";
export type {
  DitherColor,
  DitherColorName,
  DitherPalette,
  Rgba,
} from "@/lib/dither/tokens";

export {
  BLOOM_LEVELS,
  BLOOMS,
  bloomFilter,
  bloomLayerStyle,
  bloomStyle,
  ditherRamp,
  FILL_VARIANTS,
  fillStyle,
  fillTile,
  SERIES_COLORS,
  seriesColor,
} from "@/lib/dither/style";
export type {
  Bloom,
  FillEdge,
  FillStyleOptions,
  FillTile,
  FillVariant,
  RampOptions,
  RampTile,
} from "@/lib/dither/style";

export {
  readDitherCell,
  resolveColor,
  subscribeToTheme,
  useDitherColors,
} from "@/lib/dither/color";

export {
  useDocumentVisible,
  useFrameLoop,
  useInView,
  usePrefersReducedMotion,
} from "@/lib/dither/motion";
export type {
  FrameLoopCallback,
  FrameLoopOptions,
  FrameLoopState,
} from "@/lib/dither/motion";

export { DitherShader, MAX_LIVE_CONTEXTS } from "@/lib/dither/shader";
export type {
  DitherShaderProps,
  DitherShaderState,
  DitherUniforms,
  ShaderUniformValue,
} from "@/lib/dither/shader";

export { BloomBox, BloomGroup, FillPattern } from "@/lib/dither/fill";
export type {
  BloomBoxProps,
  BloomGroupProps,
  FillPatternProps,
  FillRamp,
} from "@/lib/dither/fill";

export {
  DitherPattern,
  ditherMask,
  ditherMaskStyle,
  ditherPath,
} from "@/lib/dither/pattern";
export type {
  DitherMaskOptions,
  DitherMaskStyleOptions,
  DitherPatternProps,
} from "@/lib/dither/pattern";

export { DITHER_METHODS, ditherImage } from "@/lib/dither/diffuse";
export type {
  DiffuseOptions,
  DiffusionMethod,
  DiffusionOptions,
  DitherMethod,
  ImagePalette,
  OrderedMethod,
  OrderedOptions,
  PaletteColor,
  PixelBuffer,
} from "@/lib/dither/diffuse";

import { BLUE_NOISE_64_BASE64 } from "@/lib/dither/blue-noise";

/**
 * Threshold maps for ordered dithering. A cell is inked when the tone at
 * that cell is above its threshold, so a tone of 0.25 inks a quarter of the
 * cells. Thresholds sit halfway between steps, `(rank + 0.5) / cells`, so no
 * tone ever lands exactly on one.
 */

export type DitherMatrix = "bayer2" | "bayer4" | "bayer8" | "blue-noise";

export const DITHER_MATRICES = [
  "bayer2",
  "bayer4",
  "bayer8",
  "blue-noise",
] as const satisfies readonly DitherMatrix[];

export interface ThresholdMap {
  /** Width and height in cells. The map tiles in both directions. */
  readonly size: number;
  /** Row-major thresholds in (0, 1). */
  readonly thresholds: Float32Array;
  /** Row-major ranks, 0 to `size * size - 1` (0 to 255 for blue noise). */
  readonly ranks: Uint8Array;
  /** Distinct thresholds, so `levels` tones fill it from paper to ink. */
  readonly steps: number;
}

const fromRanks = (size: number, ranks: Uint8Array, steps: number) => ({
  ranks,
  size,
  steps,
  thresholds: Float32Array.from(ranks, (rank) => (rank + 0.5) / steps),
});

// Bayer ranks: interleave the bits of (x xor y) and y, least significant
// first, so each 2x2 block of the previous size splits into four.
const bayerRanks = (size: number): Uint8Array => {
  const ranks = new Uint8Array(size * size);
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      let rank = 0;
      for (let bit = 1; bit < size; bit *= 2) {
        const xBit = Math.floor(x / bit) % 2;
        const yBit = Math.floor(y / bit) % 2;
        rank = rank * 4 + 2 * ((xBit + yBit) % 2) + yBit;
      }
      ranks[y * size + x] = rank;
    }
  }
  return ranks;
};

const decodeBase64 = (value: string): Uint8Array => {
  const binary = atob(value);
  return Uint8Array.from(binary, (char) => char.codePointAt(0) ?? 0);
};

export const BAYER_2: ThresholdMap = fromRanks(2, bayerRanks(2), 4);
export const BAYER_4: ThresholdMap = fromRanks(4, bayerRanks(4), 16);
export const BAYER_8: ThresholdMap = fromRanks(8, bayerRanks(8), 64);

/** 64x64 void-and-cluster blue noise, 256 levels of 16 cells each. */
export const BLUE_NOISE_64: ThresholdMap = fromRanks(
  64,
  decodeBase64(BLUE_NOISE_64_BASE64),
  256
);

export const getThresholdMap = (matrix: DitherMatrix): ThresholdMap => {
  switch (matrix) {
    case "bayer2": {
      return BAYER_2;
    }
    case "bayer4": {
      return BAYER_4;
    }
    case "bayer8": {
      return BAYER_8;
    }
    case "blue-noise": {
      return BLUE_NOISE_64;
    }
    default: {
      const exhaustive: never = matrix;
      return exhaustive;
    }
  }
};

const wrap = (value: number, size: number) =>
  ((Math.floor(value) % size) + size) % size;

/** The threshold in (0, 1) at cell (x, y). Coordinates wrap. */
export const thresholdAt = (matrix: DitherMatrix, x: number, y: number) => {
  const map = getThresholdMap(matrix);
  return map.thresholds[wrap(y, map.size) * map.size + wrap(x, map.size)] ?? 0;
};

/** Whether a cell is inked for a tone in [0, 1]. */
export const isInked = (
  matrix: DitherMatrix,
  x: number,
  y: number,
  tone: number
) => tone > thresholdAt(matrix, x, y);

/** A colour as red, green, blue and alpha, each in [0, 1]. */
export type Rgba = readonly [number, number, number, number];

/**
 * The named colours of the dithercn palette. `ink` is the theme's own
 * `--dither-ink`; the others are `--dither-color-<name>` from the
 * `dither-tokens` stylesheet, tuned separately for light and dark.
 */
export const DITHER_COLOR_NAMES = [
  "ink",
  "blue",
  "purple",
  "green",
  "pink",
  "orange",
  "red",
  "grey",
] as const;

export type DitherColorName = (typeof DITHER_COLOR_NAMES)[number];

/**
 * Used when a named colour's variable is missing, as in a stylesheet from
 * before the palette existed. Mid lightness, so it reads on black and white.
 */
const FALLBACKS = {
  blue: "oklch(0.64 0.16 245)",
  green: "oklch(0.68 0.16 152)",
  grey: "oklch(0.6 0 0)",
  ink: "oklch(0.6 0.2 270)",
  orange: "oklch(0.72 0.16 58)",
  pink: "oklch(0.66 0.19 352)",
  purple: "oklch(0.62 0.2 302)",
  red: "oklch(0.62 0.21 26)",
} as const satisfies Record<DitherColorName, string>;

/** The CSS variable behind each named colour. */
export const DITHER_COLORS = {
  blue: "--dither-color-blue",
  green: "--dither-color-green",
  grey: "--dither-color-grey",
  ink: "--dither-ink",
  orange: "--dither-color-orange",
  pink: "--dither-color-pink",
  purple: "--dither-color-purple",
  red: "--dither-color-red",
} as const satisfies Record<DitherColorName, `--${string}`>;

/**
 * A colour the dither components accept: a palette name such as
 * `"green"`, a CSS variable name such as `"--dither-ink"`, or any CSS
 * colour such as `"var(--chart-1)"`, `"oklch(0.7 0.15 272)"` or `"#fff"`.
 * Palette names win over the CSS keywords they share (`"red"` is the
 * dithercn red, not `#f00`).
 */
// oxlint-disable-next-line typescript/ban-types -- `string & {}` keeps editor autocomplete for the names.
export type DitherColor = DitherColorName | (string & {});

/** Colours from tone 0 (paper) to tone 1 (ink). At least two. */
export type DitherPalette = readonly [
  DitherColor,
  DitherColor,
  ...DitherColor[],
];

/** Paper to ink, from the `dither-tokens` CSS variables. */
export const DEFAULT_PALETTE = [
  "--dither-paper",
  "--dither-ink",
] as const satisfies DitherPalette;

const isColorName = (value: string): value is DitherColorName =>
  Object.hasOwn(DITHER_COLORS, value);

/**
 * A CSS colour for any `DitherColor`: `"green"` becomes
 * `"var(--dither-color-green, <fallback>)"`, `"--chart-1"` becomes `"var(--chart-1)"`,
 * and anything else passes through.
 */
export const cssColor = (value: DitherColor): string => {
  if (isColorName(value)) {
    return `var(${DITHER_COLORS[value]}, ${FALLBACKS[value]})`;
  }
  return value.startsWith("--") ? `var(${value})` : value;
};

/**
 * Motion tokens shared by every component: one ease-out curve and three
 * durations in milliseconds. `ease` matches the site's `--ease-out`.
 */
export const MOTION = {
  base: 240,
  ease: "cubic-bezier(0.23, 1, 0.32, 1)",
  fast: 150,
  slow: 600,
} as const;

"use client";

import { useEffect, useState } from "react";
import type { RefObject } from "react";

import { cssColor } from "@/lib/dither/tokens";
import type { DitherColor, Rgba } from "@/lib/dither/tokens";

const DEFAULT_CELL = 3;

let probe: CanvasRenderingContext2D | null = null;

const getProbe = () => {
  if (!probe) {
    const canvas = document.createElement("canvas");
    canvas.width = 1;
    canvas.height = 1;
    probe = canvas.getContext("2d", { willReadFrequently: true });
  }
  return probe;
};

/**
 * Resolve a colour to sRGB. CSS variables resolve in the context of `el`
 * (the document root by default), so scoped overrides apply. Any format
 * the browser understands works, including oklch, because the colour is
 * painted into a 1x1 canvas and read back.
 */
export const resolveColor = (value: DitherColor, el?: Element | null): Rgba => {
  const host = el ?? document.documentElement;
  const span = document.createElement("span");
  span.style.color = cssColor(value);
  span.style.display = "none";
  host.append(span);
  const { color } = getComputedStyle(span);
  span.remove();

  const context = getProbe();
  if (!context) {
    return [0, 0, 0, 1];
  }
  context.clearRect(0, 0, 1, 1);
  context.fillStyle = color;
  context.fillRect(0, 0, 1, 1);
  const [r = 0, g = 0, b = 0, a = 0] = context.getImageData(0, 0, 1, 1).data;
  return [r / 255, g / 255, b / 255, a / 255];
};

/** The dither cell size in CSS pixels, read from `--dither-cell` on `el`. */
export const readDitherCell = (el?: Element | null): number => {
  const host = el ?? document.documentElement;
  const value = Number.parseFloat(
    getComputedStyle(host).getPropertyValue("--dither-cell")
  );
  return Number.isFinite(value) && value > 0 ? value : DEFAULT_CELL;
};

const themeListeners = new Set<() => void>();
let themeObserver: MutationObserver | null = null;

/**
 * Call `listener` whenever the class or style of `<html>` changes, which is
 * how next-themes and most theme switchers swap palettes. One observer is
 * shared by every subscriber. Returns the unsubscribe function.
 */
export const subscribeToTheme = (listener: () => void): (() => void) => {
  themeListeners.add(listener);
  if (!themeObserver) {
    themeObserver = new MutationObserver(() => {
      for (const notify of themeListeners) {
        notify();
      }
    });
    themeObserver.observe(document.documentElement, {
      attributeFilter: ["class", "style", "data-theme"],
      attributes: true,
    });
  }
  return () => {
    themeListeners.delete(listener);
    if (themeListeners.size === 0) {
      themeObserver?.disconnect();
      themeObserver = null;
    }
  };
};

const DEFAULT_NAMES = ["--dither-ink", "--dither-paper"] as const;

type ResolvedColors<Names extends readonly DitherColor[]> = {
  readonly [Index in keyof Names]: Rgba;
};

/**
 * Resolve a list of colours (CSS variable names by default) and re-resolve
 * them when the site theme changes. Returns `null` until mounted.
 *
 * ```ts
 * const colors = useDitherColors(ref);
 * if (colors) { const [ink, paper] = colors; }
 * ```
 */
export function useDitherColors(
  el?: RefObject<Element | null>
): ResolvedColors<typeof DEFAULT_NAMES> | null;
export function useDitherColors<const Names extends readonly DitherColor[]>(
  el: RefObject<Element | null> | undefined,
  names: Names
): ResolvedColors<Names> | null;
export function useDitherColors(
  el?: RefObject<Element | null>,
  names: readonly DitherColor[] = DEFAULT_NAMES
): readonly Rgba[] | null {
  const [colors, setColors] = useState<readonly Rgba[] | null>(null);
  const key = names.join("|");

  useEffect(() => {
    const list = key === "" ? [] : key.split("|");
    const read = () =>
      setColors(list.map((name) => resolveColor(name, el?.current)));
    read();
    return subscribeToTheme(read);
  }, [el, key]);

  return colors;
}

"use client";

import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import type { RefObject } from "react";

const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)";

const subscribeToReducedMotion = (onChange: () => void) => {
  const query = window.matchMedia(REDUCED_MOTION_QUERY);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};

/** Whether the visitor asked for reduced motion. `false` on the server. */
export const usePrefersReducedMotion = (): boolean =>
  useSyncExternalStore(
    subscribeToReducedMotion,
    () => window.matchMedia(REDUCED_MOTION_QUERY).matches,
    () => false
  );

const subscribeToVisibility = (onChange: () => void) => {
  document.addEventListener("visibilitychange", onChange);
  return () => document.removeEventListener("visibilitychange", onChange);
};

/** Whether the tab is visible. `true` on the server. */
export const useDocumentVisible = (): boolean =>
  useSyncExternalStore(
    subscribeToVisibility,
    () => document.visibilityState === "visible",
    () => true
  );

/**
 * Whether the element is on screen, or within `rootMargin` of it.
 * `false` until the first observation.
 */
export const useInView = (
  ref: RefObject<Element | null>,
  { rootMargin = "120px" }: { rootMargin?: string } = {}
): boolean => {
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) {
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => setInView(entry?.isIntersecting ?? false),
      { rootMargin }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref, rootMargin]);

  return inView;
};

/**
 * `running`: drawing every frame. `paused`: offscreen or the tab is hidden.
 * `static`: motion is off (reduced motion or `enabled: false`), so the
 * callback ran once for a still frame.
 */
export type FrameLoopState = "running" | "paused" | "static";

/**
 * Called once per drawn frame with the seconds of motion so far (frozen
 * while paused) and the seconds since the previous frame (at most 0.1).
 * For the still frame drawn when motion is off, `delta` is 0 and `time` is
 * `stillTime`.
 */
export type FrameLoopCallback = (time: number, delta: number) => void;

export interface FrameLoopOptions {
  /** Pause while this element is offscreen. Omit to ignore visibility. */
  target?: RefObject<Element | null>;
  /** `false` holds a still frame, as reduced motion does. Default `true`. */
  enabled?: boolean;
  /** Frame rate cap. Default 30, which keeps slow drifts smooth. */
  fps?: number;
  /** The `time` passed for the still frame. Default 0. */
  stillTime?: number;
}

const NO_TARGET: RefObject<Element | null> = { current: null };

// One long frame (a tab switch, a debugger) must not jump the motion.
const MAX_DELTA = 0.1;

/**
 * A requestAnimationFrame loop that runs only when it can be seen. It
 * pauses offscreen and in hidden tabs, and under reduced motion (or
 * `enabled: false`) it calls `callback` once with `stillTime` instead.
 * Returns the loop state, which changes rarely, never per frame.
 */
export const useFrameLoop = (
  callback: FrameLoopCallback,
  { target, enabled = true, fps = 30, stillTime = 0 }: FrameLoopOptions = {}
): FrameLoopState => {
  const callbackRef = useRef(callback);
  useEffect(() => {
    callbackRef.current = callback;
  });

  const reducedMotion = usePrefersReducedMotion();
  const visible = useDocumentVisible();
  const inView = useInView(target ?? NO_TARGET);
  const onScreen = target ? inView : true;

  const isStatic = reducedMotion || !enabled;
  const isRunning = !isStatic && visible && onScreen;
  const timeRef = useRef(0);

  useEffect(() => {
    if (isStatic) {
      callbackRef.current(stillTime, 0);
      return;
    }
    if (!isRunning) {
      return;
    }
    const interval = 1000 / Math.max(1, fps);
    let frame = 0;
    let lastTick = performance.now();
    let lastDraw = -Infinity;
    const tick = (now: number) => {
      frame = requestAnimationFrame(tick);
      const delta = Math.min((now - lastTick) / 1000, MAX_DELTA);
      lastTick = now;
      timeRef.current += delta;
      // A small tolerance so 60Hz screens hit 30fps evenly.
      if (now - lastDraw >= interval - 2) {
        const sinceDraw = Math.min((now - lastDraw) / 1000, MAX_DELTA);
        lastDraw = now;
        callbackRef.current(timeRef.current, sinceDraw);
      }
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [isStatic, isRunning, fps, stillTime]);

  if (isStatic) {
    return "static";
  }
  return isRunning ? "running" : "paused";
};

/**
 * Source handling for the GLSL a `DitherShader` compiles. No imports, so
 * it runs anywhere, including the tests next to it.
 */

const COMMENTS = /\/\*[\s\S]*?\*\/|\/\/[^\r\n]*/g;
const DIRECTIVE = /^[ \t]*#/m;
const STRUCT = /^\s*(?:(?:lowp|mediump|highp|const|uniform)\s+)*struct\b/;
const PRECISION = /^\s*precision\b/;
// GLSL tokens: numbers (with any exponent), names, the two-character
// operators, then any other single character, `.` included. So `p.x` and
// `p . x` match, while `a + ++b` and `a++ +b` stay different.
const TOKEN =
  /\d+\.\d*(?:[eE][-+]?\d+)?|\.\d+(?:[eE][-+]?\d+)?|\d+(?:[eE][-+]?\d+)?|[A-Za-z_]\w*|\+\+|--|<=|>=|==|!=|&&|\|\||\^\^|[-+*/]=|\S/g;

/**
 * GLSL without directives, split at the top level with comments dropped:
 * declarations ending in `;` and definitions ending in their `}`.
 */
const topLevelChunks = (source: string): string[] => {
  const code = source.replaceAll(COMMENTS, " ");
  const chunks: string[] = [];
  let depth = 0;
  let start = 0;
  const cut = (end: number) => {
    const chunk = code.slice(start, end).trim();
    start = end;
    if (chunk !== "") {
      chunks.push(chunk);
    }
  };
  for (let index = 0; index < code.length; index += 1) {
    const char = code[index];
    if (char === "{") {
      depth += 1;
    } else if (char === "}") {
      depth -= 1;
      // A struct declaration runs on to its `;`, which may name variables.
      if (depth === 0 && !STRUCT.test(code.slice(start, index))) {
        cut(index + 1);
      }
    } else if (char === ";" && depth === 0) {
      cut(index + 1);
    }
  }
  cut(code.length);
  return chunks;
};

const tokens = (chunk: string) => chunk.match(TOKEN)?.join(" ") ?? "";

const hasDirective = (source: string) =>
  DIRECTIVE.test(source.replaceAll(COMMENTS, " "));

/**
 * `field` and `colorField` compile into one shader, where defining a helper
 * twice is an error. A common way to share one is to prepend the same
 * string to both, so drop any definition from `colorField` that `field`
 * already has, token for token. Two different definitions still fail.
 * Sources with preprocessor directives are left alone: a definition's
 * meaning can depend on `#if` and `#define` around it. `precision`
 * statements are always kept, since each sets the precision for the code
 * after it.
 */
export const withoutSharedHelpers = (
  field: string,
  colorField: string
): string => {
  if (hasDirective(field) || hasDirective(colorField)) {
    return colorField;
  }
  const defined = new Set(topLevelChunks(field).map(tokens));
  return topLevelChunks(colorField)
    .filter((chunk) => PRECISION.test(chunk) || !defined.has(tokens(chunk)))
    .join("\n");
};

"use client";

import { useEffect, useRef, useState } from "react";
import type { ComponentProps, ReactNode, RefObject } from "react";

import {
  readDitherCell,
  resolveColor,
  subscribeToTheme,
} from "@/lib/dither/color";
import { withoutSharedHelpers } from "@/lib/dither/glsl";
import { getThresholdMap } from "@/lib/dither/matrices";
import type { DitherMatrix, ThresholdMap } from "@/lib/dither/matrices";
import { useFrameLoop, usePrefersReducedMotion } from "@/lib/dither/motion";
import { cssColor, DEFAULT_PALETTE } from "@/lib/dither/tokens";
import type { DitherPalette, Rgba } from "@/lib/dither/tokens";
import { cn } from "@/lib/utils";

export type ShaderUniformValue =
  | number
  | readonly [number, number]
  | readonly [number, number, number]
  | readonly [number, number, number, number];

export type DitherUniforms = Readonly<Record<string, ShaderUniformValue>>;

export type DitherShaderState = "fallback" | "running" | "paused" | "static";

/**
 * GLSL helpers available to every field. Names starting with `u_` are
 * reserved for the core's own uniforms, and `dither_` for its helpers.
 *
 * - `float hash21(vec2 p)`: a stable pseudo-random value in [0, 1).
 * - `float snoise(vec2 p)`: 2D simplex noise in [-1, 1].
 * - `float fbm(vec2 p)`: four octaves of simplex noise, in [0, 1].
 * - `vec3 spectrum(float h)`: a saturated rainbow. 0 is red, then yellow,
 *   green, cyan, blue and magenta, back to red at 1; it wraps.
 * - `vec4 paletteColor(float x)`: the palette's ink colours, every entry
 *   after the paper, as a smooth ramp from x = 0 to 1.
 */
const GLSL_HELPERS = `
float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

vec3 dither_permute(vec3 x) {
  return mod(((x * 34.0) + 1.0) * x, 289.0);
}

float snoise(vec2 v) {
  const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
  vec2 i = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);
  vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;
  i = mod(i, 289.0);
  vec3 p = dither_permute(dither_permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));
  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
  m = m * m;
  m = m * m;
  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;
  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);
  vec3 g;
  g.x = a0.x * x0.x + h.x * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}

float fbm(vec2 p) {
  float sum = 0.0;
  float amp = 0.5;
  mat2 rotate = mat2(0.8, -0.6, 0.6, 0.8);
  for (int i = 0; i < 4; i++) {
    sum += amp * snoise(p);
    p = rotate * p * 2.02 + vec2(11.3, 4.7);
    amp *= 0.5;
  }
  return clamp(0.5 + 0.5 * sum / 0.9375, 0.0, 1.0);
}

vec3 spectrum(float h) {
  vec3 rgb = clamp(abs(mod(fract(h) * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
  return rgb * rgb * (3.0 - 2.0 * rgb);
}

vec4 dither_paletteEntry(float index) {
  return texture2D(u_palette, vec2((index + 0.5) / u_paletteSize, 0.5));
}

vec4 paletteColor(float x) {
  float last = u_paletteSize - 1.0;
  float scaled = clamp(x, 0.0, 1.0) * (last - 1.0);
  float index = floor(scaled);
  vec4 from = dither_paletteEntry(1.0 + index);
  vec4 to = dither_paletteEntry(min(2.0 + index, last));
  return mix(from, to, scaled - index);
}

vec4 dither_rgba(vec3 color) {
  return vec4(color, 1.0);
}

vec4 dither_rgba(vec4 color) {
  return color;
}
`;

const VERTEX_SHADER = `
attribute vec2 a_position;
void main() {
  gl_Position = vec4(a_position, 0.0, 1.0);
}
`;

interface UniformSpec {
  readonly name: string;
  readonly size: 1 | 2 | 3 | 4;
}

const IDENTIFIER = /^[A-Za-z][A-Za-z0-9_]*$/;
const GLSL_TYPES = { 1: "float", 2: "vec2", 3: "vec3", 4: "vec4" } as const;

const uniformSize = (value: ShaderUniformValue): UniformSpec["size"] =>
  typeof value === "number" ? 1 : value.length;

const uniformSpecs = (uniforms: DitherUniforms): UniformSpec[] =>
  Object.keys(uniforms)
    .toSorted()
    .flatMap((name) => {
      const value = uniforms[name];
      if (value === undefined) {
        return [];
      }
      if (!IDENTIFIER.test(name) || name.startsWith("u_")) {
        // Reserved or invalid names would break the shader; say which.
        console.error(
          `[dither-core] uniform "${name}" skipped: names must be GLSL identifiers and not start with "u_"`
        );
        return [];
      }
      return [{ name, size: uniformSize(value) }];
    });

// With a colour field, a cell is either paper or the colour field's colour
// there, chosen by the same tone and threshold as a two-colour palette.
const PALETTE_COLOR = `
  float scaled = tone * (u_paletteSize - 1.0);
  float index = floor(scaled);
  index = min(index + step(threshold, scaled - index), u_paletteSize - 1.0);
  vec4 color = dither_paletteEntry(index);`;

const FIELD_COLOR = `
  float ink = min(floor(tone) + step(threshold, fract(tone)), 1.0);
  vec4 color = ink > 0.5
    ? dither_rgba(colorField(uv, u_resolution, u_time))
    : dither_paletteEntry(0.0);
  color = clamp(color, 0.0, 1.0);`;

const fragmentShader = (
  field: string,
  colorField: string | undefined,
  specs: readonly UniformSpec[]
) => `
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform float u_levels;
uniform sampler2D u_thresholds;
uniform float u_matrixSize;
uniform float u_rankStep;
uniform sampler2D u_palette;
uniform float u_paletteSize;
${specs.map(({ name, size }) => `uniform ${GLSL_TYPES[size]} ${name};`).join("\n")}
${GLSL_HELPERS}
${field}
${colorField === undefined ? "" : withoutSharedHelpers(field, colorField)}

void main() {
  vec2 cell = floor(gl_FragCoord.xy);
  vec2 uv = (cell + 0.5) / u_resolution;
  float tone = clamp(field(uv, u_resolution, u_time), 0.0, 1.0);
  float steps = u_levels - 1.0;
  tone = floor(tone * steps + 0.5) / steps;

  // Ranks are stored as rank * (256 / steps), so this threshold is exactly
  // (rank + 0.5) / steps, halfway between two tones.
  vec2 at = (mod(cell, u_matrixSize) + 0.5) / u_matrixSize;
  float stored = floor(texture2D(u_thresholds, at).r * 255.0 + 0.5);
  float threshold = (stored + 0.5 * u_rankStep) / 256.0;

${colorField === undefined ? PALETTE_COLOR : FIELD_COLOR}
  gl_FragColor = vec4(color.rgb * color.a, color.a);
}
`;

interface DrawInput {
  readonly columns: number;
  readonly rows: number;
  readonly time: number;
  readonly levels: number;
  readonly uniforms: DitherUniforms;
}

interface Renderer {
  readonly setMatrix: (map: ThresholdMap) => void;
  readonly setPalette: (colors: readonly Rgba[]) => void;
  readonly draw: (input: DrawInput) => void;
  readonly dispose: () => void;
}

const compile = (gl: WebGLRenderingContext, type: GLenum, source: string) => {
  const shader = gl.createShader(type);
  if (!shader) {
    return null;
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    if (!gl.isContextLost()) {
      // A broken `field` is a bug in the calling component; say why.
      const log = gl.getShaderInfoLog(shader) ?? "";
      console.error("[dither-core] shader failed to compile", log);
      if (log.includes("already has a body")) {
        console.error(
          "[dither-core] a function is defined twice. `field` and `colorField` compile into one shader: give helpers different names, or define a shared helper once, in `field`, and call it from both."
        );
      }
    }
    gl.deleteShader(shader);
    return null;
  }
  return shader;
};

const createTexture = (gl: WebGLRenderingContext) => {
  const texture = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  return texture;
};

const createRenderer = (
  gl: WebGLRenderingContext,
  {
    field,
    colorField,
    specs,
  }: {
    field: string;
    colorField: string | undefined;
    specs: readonly UniformSpec[];
  }
): Renderer | null => {
  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX_SHADER);
  const fragment = compile(
    gl,
    gl.FRAGMENT_SHADER,
    fragmentShader(field, colorField, specs)
  );
  const program = gl.createProgram();
  if (!vertex || !fragment || !program) {
    return null;
  }
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }
  gl.useProgram(program);

  // One triangle that covers the viewport.
  const buffer = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW
  );
  const position = gl.getAttribLocation(program, "a_position");
  gl.enableVertexAttribArray(position);
  gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);

  const location = (name: string) => gl.getUniformLocation(program, name);
  const uResolution = location("u_resolution");
  const uTime = location("u_time");
  const uLevels = location("u_levels");
  const uMatrixSize = location("u_matrixSize");
  const uRankStep = location("u_rankStep");
  const uPaletteSize = location("u_paletteSize");
  gl.uniform1i(location("u_thresholds"), 0);
  gl.uniform1i(location("u_palette"), 1);
  const custom = specs.map((spec) => ({
    ...spec,
    location: location(spec.name),
  }));

  const thresholds = createTexture(gl);
  const palette = createTexture(gl);
  gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);

  return {
    dispose: () => {
      gl.deleteTexture(thresholds);
      gl.deleteTexture(palette);
      gl.deleteBuffer(buffer);
      gl.deleteProgram(program);
    },
    draw: ({ columns, rows, time, levels, uniforms }) => {
      gl.viewport(0, 0, columns, rows);
      gl.uniform2f(uResolution, columns, rows);
      gl.uniform1f(uTime, time);
      gl.uniform1f(uLevels, levels);
      for (const spec of custom) {
        const value = uniforms[spec.name];
        if (value === undefined) {
          continue;
        }
        if (typeof value === "number") {
          gl.uniform1f(spec.location, value);
        } else if (value.length === 2) {
          gl.uniform2f(spec.location, value[0], value[1]);
        } else if (value.length === 3) {
          gl.uniform3f(spec.location, value[0], value[1], value[2]);
        } else {
          gl.uniform4f(spec.location, value[0], value[1], value[2], value[3]);
        }
      }
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    },
    setMatrix: (map) => {
      const rankStep = 256 / map.steps;
      const bytes = Uint8Array.from(map.ranks, (rank) => rank * rankStep);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, thresholds);
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.LUMINANCE,
        map.size,
        map.size,
        0,
        gl.LUMINANCE,
        gl.UNSIGNED_BYTE,
        bytes
      );
      gl.uniform1f(uMatrixSize, map.size);
      gl.uniform1f(uRankStep, rankStep);
    },
    setPalette: (colors) => {
      const bytes = new Uint8Array(colors.length * 4);
      for (const [index, color] of colors.entries()) {
        bytes.set(
          color.map((channel) => Math.round(channel * 255)),
          index * 4
        );
      }
      gl.activeTexture(gl.TEXTURE1);
      gl.bindTexture(gl.TEXTURE_2D, palette);
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        colors.length,
        1,
        0,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        bytes
      );
      gl.uniform1f(uPaletteSize, colors.length);
    },
  };
};

/**
 * Browsers cap live WebGL contexts (Chrome drops the oldest past 16), so
 * every DitherShader on the page shares a budget. A shader holds a context
 * only while it is near the viewport. Past the budget, a shader coming on
 * screen takes the context of one just outside the viewport, seen least
 * recently first. It never takes one from a shader still on screen, so
 * scrolling doesn't flip visible shaders between canvas and fallback;
 * it waits instead, and gets the next context freed.
 */
export const MAX_LIVE_CONTEXTS = 8;

interface ContextSlot {
  near: boolean;
  onScreen: boolean;
  lastSeen: number;
  active: boolean;
  readonly setActive: (active: boolean) => void;
}

const slots = new Set<ContextSlot>();

const activate = (slot: ContextSlot, active: boolean) => {
  slot.active = active;
  slot.setActive(active);
};

const leastRecent = (candidates: Iterable<ContextSlot>) => {
  let oldest: ContextSlot | null = null;
  for (const slot of candidates) {
    if (!oldest || slot.lastSeen < oldest.lastSeen) {
      oldest = slot;
    }
  }
  return oldest;
};

const requestContext = (slot: ContextSlot) => {
  if (slot.active) {
    return;
  }
  const live = [...slots].filter((other) => other.active);
  if (live.length >= MAX_LIVE_CONTEXTS) {
    const offscreen = live.filter((other) => !other.onScreen);
    const victim = slot.onScreen ? leastRecent(offscreen) : null;
    if (!victim) {
      return;
    }
    activate(victim, false);
  }
  activate(slot, true);
};

const releaseContext = (slot: ContextSlot) => {
  if (!slot.active) {
    return;
  }
  activate(slot, false);
  // A freed context goes to the shader that waited longest, on screen first.
  const waiting = [...slots].filter((other) => other.near && !other.active);
  const onScreen = waiting.filter((other) => other.onScreen);
  const next = leastRecent(onScreen.length > 0 ? onScreen : waiting);
  if (next) {
    activate(next, true);
  }
};

const hasOnScreenWaiter = () =>
  [...slots].some((other) => other.onScreen && other.near && !other.active);

/** Holds a slot in the shared context budget while `ref` is near the viewport. */
const useContextSlot = (ref: RefObject<Element | null>): boolean => {
  const [active, setActive] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) {
      return;
    }
    const slot: ContextSlot = {
      active: false,
      lastSeen: 0,
      near: false,
      onScreen: false,
      setActive,
    };
    slots.add(slot);
    const nearObserver = new IntersectionObserver(
      ([entry]) => {
        slot.near = entry?.isIntersecting ?? false;
        if (slot.near) {
          slot.lastSeen = performance.now();
          requestContext(slot);
        } else {
          releaseContext(slot);
        }
      },
      { rootMargin: "200px" }
    );
    // Coming on screen can take a context from one that is only nearby, and
    // leaving the screen hands it to an on-screen shader that is waiting.
    const screenObserver = new IntersectionObserver(([entry]) => {
      slot.onScreen = entry?.isIntersecting ?? false;
      if (slot.onScreen && slot.near) {
        slot.lastSeen = performance.now();
        requestContext(slot);
      } else if (!slot.onScreen && slot.active && hasOnScreenWaiter()) {
        releaseContext(slot);
      }
    });
    nearObserver.observe(el);
    screenObserver.observe(el);
    return () => {
      nearObserver.disconnect();
      screenObserver.disconnect();
      // Leave the set first, so the freed context goes to someone else.
      slots.delete(slot);
      releaseContext(slot);
    };
  }, [ref]);

  return active;
};

export interface DitherShaderProps extends Omit<
  ComponentProps<"div">,
  "children"
> {
  /**
   * GLSL that defines `float field(vec2 uv, vec2 res, float t)`, returning
   * the tone in [0, 1] for one cell: 0 is paper, 1 is ink. `uv` is the
   * cell centre in [0, 1] with y pointing up, `res` the size in cells, `t`
   * the time in seconds (scaled by `speed`). May define helpers too.
   */
  field: string;
  /**
   * GLSL that defines `colorField(vec2 uv, vec2 res, float t)`, returning
   * the ink colour for one cell as `vec3` or `vec4` RGB(A) in [0, 1], with
   * the same arguments as `field`. Set it when colour should vary on its
   * own: a rainbow, a hue per shape. The field's tone still decides where
   * the dots go, and each dot takes this colour; cells without a dot are
   * paper (`palette[0]`). `spectrum(h)` and `paletteColor(x)` help.
   */
  colorField?: string;
  /**
   * Extra uniforms, declared for you by name: numbers become `float`,
   * tuples `vec2` to `vec4`. Names must not start with `u_`.
   */
  uniforms?: DitherUniforms;
  /** Threshold matrix. Default `"bayer4"`. */
  matrix?: DitherMatrix;
  /** Tones the field snaps to before dithering, 2 to 256. Default: every tone the matrix can draw. */
  levels?: number;
  /** Cell size in CSS pixels. Default: `--dither-cell`, or 3. */
  cell?: number;
  /**
   * Colours from paper (tone 0) to ink (tone 1). Default
   * `["--dither-paper", "--dither-ink"]`. With `colorField`, the first is
   * the paper and the rest are what `paletteColor` reads.
   */
  palette?: DitherPalette;
  /** Time multiplier. Default 1. */
  speed?: number;
  /**
   * `false` stops the motion. A shader that never moved draws `stillTime`;
   * one that was moving holds its current frame. Default `true`.
   */
  animate?: boolean;
  /** Frame rate cap. Default 30. */
  fps?: number;
  /** The moment shown when motion is off or reduced, in field seconds. Default 0. */
  stillTime?: number;
  /**
   * Painted until the first WebGL frame, while the shader is far offscreen,
   * and whenever WebGL is unavailable. Default: flat paper.
   */
  fallback?: ReactNode;
}

const NO_UNIFORMS: DitherUniforms = {};

const clampLevels = (levels: number) =>
  Math.min(256, Math.max(2, Math.round(levels)));

const CANVAS_CLASS =
  "absolute top-0 left-0 block opacity-100 transition-opacity duration-700 ease-out [image-rendering:pixelated] group-data-[state=fallback]/dither:opacity-0 group-data-[state=fallback]/dither:duration-0 motion-reduce:transition-none";

/**
 * A dithered full-bleed canvas driven by a GLSL `field`. Renders one pixel
 * per dither cell, scaled up with crisp edges. Pauses offscreen and in
 * hidden tabs, holds a still frame under reduced motion, follows the theme,
 * and shows `fallback` without WebGL or while far offscreen. `data-state`
 * reports `fallback`, `running`, `paused` or `static`.
 */
export const DitherShader = ({
  field,
  colorField,
  uniforms = NO_UNIFORMS,
  matrix = "bayer4",
  levels,
  cell,
  palette = DEFAULT_PALETTE,
  speed = 1,
  animate = true,
  fps = 30,
  stillTime = 0,
  fallback,
  className,
  "aria-hidden": ariaHidden = true,
  ref,
  ...props
}: DitherShaderProps) => {
  const rootRef = useRef<HTMLDivElement>(null);
  // The root is ours and the caller's: keep both refs pointing at it.
  const setRoot = (node: HTMLDivElement | null) => {
    rootRef.current = node;
    if (typeof ref === "function") {
      return ref(node);
    }
    if (ref) {
      ref.current = node;
    }
  };
  const rendererRef = useRef<Renderer | null>(null);
  const sizeRef = useRef({ columns: 0, rows: 0 });
  const timeRef = useRef(stillTime);
  const [hasFrame, setHasFrame] = useState(false);
  const hasFrameRef = useRef(false);
  const hasContext = useContextSlot(rootRef);

  const map = getThresholdMap(matrix);
  const resolvedLevels = clampLevels(levels ?? map.steps + 1);
  const paletteKey = palette.join("|");
  const specs = uniformSpecs(uniforms);
  const specKey = specs.map(({ name, size }) => `${name}:${size}`).join(",");

  const markFrame = (drawn: boolean) => {
    if (hasFrameRef.current !== drawn) {
      hasFrameRef.current = drawn;
      setHasFrame(drawn);
    }
  };

  // Everything a draw reads, kept current without restarting effects.
  const live = useRef({
    levels: resolvedLevels,
    map,
    paletteKey,
    speed,
    uniforms,
  });
  const drawRef = useRef<(() => void) | null>(null);
  useEffect(() => {
    live.current = { levels: resolvedLevels, map, paletteKey, speed, uniforms };
    drawRef.current = () => {
      const renderer = rendererRef.current;
      const { columns, rows } = sizeRef.current;
      if (!renderer || columns === 0 || rows === 0) {
        return;
      }
      renderer.draw({
        columns,
        levels: live.current.levels,
        rows,
        time: timeRef.current,
        uniforms: live.current.uniforms,
      });
      markFrame(true);
    };
  });

  // Once motion has run, turning `animate` off holds the frame on screen
  // instead of jumping to `stillTime`. A new `stillTime` still applies, and
  // reduced motion always shows it.
  const reducedMotion = usePrefersReducedMotion();
  const hasRunRef = useRef(false);
  useEffect(() => {
    hasRunRef.current = false;
  }, [stillTime]);

  const loopState = useFrameLoop(
    (time, delta) => {
      if (delta > 0) {
        // Accumulate so a change of `speed` never jumps the motion.
        timeRef.current += delta * live.current.speed;
        hasRunRef.current = true;
      } else if (reducedMotion || !hasRunRef.current) {
        timeRef.current = time;
      }
      drawRef.current?.();
    },
    { enabled: animate, fps, stillTime, target: rootRef }
  );

  // Context, program, size and theme. A fresh canvas per context, so a
  // released context never has to be restored.
  useEffect(() => {
    const root = rootRef.current;
    if (!root || !hasContext) {
      return;
    }
    const canvas = document.createElement("canvas");
    canvas.className = CANVAS_CLASS;
    const gl = canvas.getContext("webgl", {
      alpha: true,
      antialias: false,
      depth: false,
      powerPreference: "low-power",
      premultipliedAlpha: true,
      stencil: false,
    });
    if (!gl) {
      return;
    }
    root.append(canvas);

    const resolvePalette = () =>
      live.current.paletteKey
        .split("|")
        .map((color) => resolveColor(color, root));

    const build = () => {
      rendererRef.current?.dispose();
      const renderer = createRenderer(gl, { colorField, field, specs });
      rendererRef.current = renderer;
      renderer?.setMatrix(live.current.map);
      renderer?.setPalette(resolvePalette());
    };

    const resize = () => {
      const dpr = window.devicePixelRatio || 1;
      const cssCell = cell ?? readDitherCell(root);
      // Whole device pixels per cell, so every cell is the same size.
      const deviceCell = Math.max(1, Math.round(cssCell * dpr));
      const snapped = deviceCell / dpr;
      // Layout size, not the painted box, so a scaled parent (a zoom-in
      // animation, a thumbnail) doesn't shrink the grid. The computed size
      // keeps fractions that offsetWidth rounds away, so the last column
      // still reaches the edge of a 300.4px box.
      const style = getComputedStyle(root);
      const width = Number.parseFloat(style.width) || root.offsetWidth;
      const height = Number.parseFloat(style.height) || root.offsetHeight;
      const columns = Math.max(1, Math.ceil(width / snapped));
      const rows = Math.max(1, Math.ceil(height / snapped));
      sizeRef.current = { columns, rows };
      canvas.width = columns;
      canvas.height = rows;
      canvas.style.width = `${columns * snapped}px`;
      canvas.style.height = `${rows * snapped}px`;
      drawRef.current?.();
    };

    const onThemeChange = () => {
      rendererRef.current?.setPalette(resolvePalette());
      drawRef.current?.();
    };
    const onContextLost = (event: Event) => {
      event.preventDefault();
      rendererRef.current = null;
      markFrame(false);
    };
    const onContextRestored = () => {
      build();
      drawRef.current?.();
    };

    build();
    resize();
    const resizeObserver = new ResizeObserver(resize);
    resizeObserver.observe(root);
    const unsubscribe = subscribeToTheme(onThemeChange);
    canvas.addEventListener("webglcontextlost", onContextLost);
    canvas.addEventListener("webglcontextrestored", onContextRestored);

    return () => {
      resizeObserver.disconnect();
      unsubscribe();
      canvas.removeEventListener("webglcontextlost", onContextLost);
      canvas.removeEventListener("webglcontextrestored", onContextRestored);
      rendererRef.current?.dispose();
      rendererRef.current = null;
      gl.getExtension("WEBGL_lose_context")?.loseContext();
      canvas.remove();
      markFrame(false);
    };
    // `specs` is described by `specKey`; a new `cell` re-measures.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [field, colorField, specKey, cell, hasContext]);

  useEffect(() => {
    rendererRef.current?.setMatrix(map);
  }, [map]);

  useEffect(() => {
    const root = rootRef.current;
    if (root) {
      rendererRef.current?.setPalette(
        paletteKey.split("|").map((color) => resolveColor(color, root))
      );
    }
  }, [paletteKey]);

  // Props changed while nothing is animating: redraw the held frame.
  useEffect(() => {
    if (loopState !== "running") {
      drawRef.current?.();
    }
  });

  const state: DitherShaderState = hasFrame ? loopState : "fallback";

  return (
    <div
      ref={setRoot}
      aria-hidden={ariaHidden}
      data-state={state}
      className={cn(
        "group/dither pointer-events-none relative overflow-hidden",
        className
      )}
      {...props}
    >
      <div
        data-dither-fallback
        className="absolute inset-0 opacity-0 transition-opacity delay-700 duration-0 group-data-[state=fallback]/dither:opacity-100 group-data-[state=fallback]/dither:delay-0"
      >
        {fallback ?? (
          <div
            className="absolute inset-0"
            style={{ backgroundColor: cssColor(palette[0]) }}
          />
        )}
      </div>
    </div>
  );
};

import type { CSSProperties } from "react";

import { getThresholdMap } from "@/lib/dither/matrices";
import type { DitherMatrix } from "@/lib/dither/matrices";
import { cssColor } from "@/lib/dither/tokens";
import type { DitherColor } from "@/lib/dither/tokens";

/**
 * Static dithers without a canvas: an SVG `<pattern>` for chart fills and a
 * CSS mask for any element. Both are pure and render on the server.
 * `level` is the share of cells inked, from 0 (none) to 1 (all).
 */

const pathCache = new Map<string, string>();

/**
 * One SVG path covering the inked cells of one matrix tile, in cell units.
 * Runs of neighbouring cells in a row merge into one rectangle.
 */
export const ditherPath = (level: number, matrix: DitherMatrix = "bayer4") => {
  const key = `${matrix}:${level}`;
  const cached = pathCache.get(key);
  if (cached !== undefined) {
    return cached;
  }
  const { size, thresholds } = getThresholdMap(matrix);
  let path = "";
  for (let y = 0; y < size; y += 1) {
    let start = -1;
    for (let x = 0; x <= size; x += 1) {
      const inked = x < size && level > (thresholds[y * size + x] ?? 1);
      if (inked && start === -1) {
        start = x;
      } else if (!inked && start !== -1) {
        path += `M${start} ${y}h${x - start}v1h${start - x}z`;
        start = -1;
      }
    }
  }
  pathCache.set(key, path);
  return path;
};

export interface DitherMaskOptions {
  /** Threshold matrix. Default `"bayer4"`. */
  matrix?: DitherMatrix;
  /**
   * Cell size in CSS pixels. When set, the image has that intrinsic size
   * and tiles without a `mask-size`. Leave it unset to size the tile
   * yourself, for example with `ditherMaskStyle`.
   */
  cell?: number;
}

/**
 * A CSS `mask-image` value: one matrix tile with the cells below `level`
 * filled. Paint the element with the ink colour and mask it.
 */
export const ditherMask = (
  level: number,
  { matrix = "bayer4", cell }: DitherMaskOptions = {}
) => {
  const { size } = getThresholdMap(matrix);
  const dimensions =
    cell === undefined ? "" : ` width="${size * cell}" height="${size * cell}"`;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${size} ${size}"${dimensions} shape-rendering="crispEdges"><path d="${ditherPath(level, matrix)}"/></svg>`;
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
};

export interface DitherMaskStyleOptions {
  /** Threshold matrix. Default `"bayer4"`. */
  matrix?: DitherMatrix;
  /** Cell size: CSS pixels, or any CSS length. Default `var(--dither-cell)`. */
  cell?: number | string;
}

/**
 * Inline styles that mask an element to one dither level, tiled at the
 * cell size. Pair with a background colour such as `bg-dither-ink`.
 *
 * ```tsx
 * <div className="bg-dither-ink" style={ditherMaskStyle(0.5)} />
 * ```
 */
export const ditherMaskStyle = (
  level: number,
  {
    matrix = "bayer4",
    cell = "var(--dither-cell)",
  }: DitherMaskStyleOptions = {}
): CSSProperties => {
  const { size } = getThresholdMap(matrix);
  const image = ditherMask(level, { matrix });
  const tile =
    typeof cell === "number" ? `${size * cell}px` : `calc(${cell} * ${size})`;
  return {
    WebkitMaskImage: image,
    WebkitMaskRepeat: "repeat",
    WebkitMaskSize: tile,
    maskImage: image,
    maskRepeat: "repeat",
    maskSize: tile,
  };
};

export interface DitherPatternProps {
  /** The id to reference, as in `fill="url(#id)"`. */
  id: string;
  /** Share of cells inked, 0 to 1. */
  level: number;
  /** Threshold matrix. Default `"bayer4"`. */
  matrix?: DitherMatrix;
  /** Cell size in SVG user units (CSS pixels when the SVG is not scaled). Default 3. */
  cell?: number;
  /** Ink colour. Default `--dither-ink`. */
  color?: DitherColor;
  /** Colour behind the ink. Default: transparent. */
  background?: DitherColor;
}

/**
 * An SVG `<pattern>` filled with one dither level. Place it inside `<defs>`
 * and fill shapes with `url(#id)`. Colours accept CSS variables, so the
 * fill follows the theme.
 */
export const DitherPattern = ({
  id,
  level,
  matrix = "bayer4",
  cell = 3,
  color = "--dither-ink",
  background,
}: DitherPatternProps) => {
  const { size } = getThresholdMap(matrix);
  const tile = size * cell;
  return (
    <pattern
      id={id}
      width={tile}
      height={tile}
      patternUnits="userSpaceOnUse"
      shapeRendering="crispEdges"
    >
      {background === undefined ? null : (
        <rect
          width={tile}
          height={tile}
          style={{ fill: cssColor(background) }}
        />
      )}
      <path
        d={ditherPath(level, matrix)}
        transform={`scale(${cell})`}
        style={{ fill: cssColor(color) }}
      />
    </pattern>
  );
};

import type { CSSProperties } from "react";

import { getThresholdMap } from "@/lib/dither/matrices";
import type { DitherMatrix } from "@/lib/dither/matrices";
import { ditherMask } from "@/lib/dither/pattern";
import { cssColor } from "@/lib/dither/tokens";
import type { DitherColor, DitherColorName } from "@/lib/dither/tokens";

/**
 * The style kit: fill variants, bloom and the default series palette.
 * Everything here is pure and server-safe. The SVG pieces that use it
 * (`FillPattern`, `BloomGroup`, `Bloom`) live in `pattern.tsx`.
 */

/**
 * How a shape is filled.
 * `gradient`: dense at the leading edge, thinning through dither levels.
 * `dotted`: a sparse staggered lattice of single cells.
 * `hatched`: diagonal lines one cell wide.
 * `solid`: flat colour.
 */
export const FILL_VARIANTS = [
  "gradient",
  "dotted",
  "hatched",
  "solid",
] as const;
export type FillVariant = (typeof FILL_VARIANTS)[number];

/** The side of a shape where a gradient fill is densest. */
export type FillEdge = "top" | "bottom" | "left" | "right";

/** A soft glow in the fill's colour behind it. */
export const BLOOMS = ["off", "low", "high"] as const;
export type Bloom = (typeof BLOOMS)[number];

/**
 * Series colours in order: distinct hues, so two or more series never
 * rely on texture alone.
 */
export const SERIES_COLORS = [
  "ink",
  "orange",
  "green",
  "pink",
  "purple",
  "blue",
  "red",
  "grey",
] as const satisfies readonly [DitherColorName, ...DitherColorName[]];

/** The colour of series `index`: its own, or the next palette colour. */
export const seriesColor = (color: DitherColor | undefined, index: number) =>
  color ?? SERIES_COLORS[index % SERIES_COLORS.length] ?? "ink";

/** Write one SVG path covering the inked cells of a grid, in cell units. */
const cellsPath = (
  width: number,
  height: number,
  inked: (x: number, y: number) => boolean
) => {
  let path = "";
  for (let y = 0; y < height; y += 1) {
    let start = -1;
    for (let x = 0; x <= width; x += 1) {
      const on = x < width && inked(x, y);
      if (on && start === -1) {
        start = x;
      } else if (!on && start !== -1) {
        path += `M${start} ${y}h${x - start}v1h${start - x}z`;
        start = -1;
      }
    }
  }
  return path;
};

/** One tile of a texture: its side in cells and the inked cells as a path. */
export interface FillTile {
  size: number;
  path: string;
}

// Dots on a staggered lattice: every other cell, rows offset by one.
const DOTTED: FillTile = {
  path: cellsPath(4, 4, (x, y) => y % 2 === 0 && (x + y / 2) % 2 === 0),
  size: 4,
};

// Rising diagonals, one cell wide, four cells apart.
const HATCHED: FillTile = {
  path: cellsPath(4, 4, (x, y) => (x + y) % 4 === 3),
  size: 4,
};

/** The repeating tile of a textured variant. */
export const fillTile = (variant: "dotted" | "hatched"): FillTile =>
  variant === "dotted" ? DOTTED : HATCHED;

export interface RampOptions {
  /** Side where the ramp is densest. */
  edge: FillEdge;
  /** Length of the fade in cells. */
  length: number;
  /** Total length of the tile in cells, at least `length`. Past the fade it holds `to`. */
  extent?: number;
  /** Coverage at the edge, 0 to 1. */
  from: number;
  /** Coverage at the far end of the fade, 0 to 1. */
  to: number;
  /** Threshold matrix. Default `bayer4`. */
  matrix?: DitherMatrix;
}

export interface RampTile {
  /** Tile width in cells. */
  width: number;
  /** Tile height in cells. */
  height: number;
  path: string;
}

const rampCache = new Map<string, RampTile>();

/**
 * A dithered ramp: coverage falls linearly from `from` at `edge` to `to`
 * over `length` cells, then holds. The tile is one matrix wide across the
 * ramp, and its length is rounded up to whole matrices so it lines up with
 * a plain dither of the same matrix.
 */
export const ditherRamp = ({
  edge,
  length,
  extent = length,
  from,
  to,
  matrix = "bayer4",
}: RampOptions): RampTile => {
  const key = `${edge}:${length}:${extent}:${from}:${to}:${matrix}`;
  const cached = rampCache.get(key);
  if (cached !== undefined) {
    return cached;
  }
  const { size, thresholds } = getThresholdMap(matrix);
  const fade = Math.max(1, Math.round(length));
  const along = Math.ceil(Math.max(fade, extent) / size) * size;
  const vertical = edge === "top" || edge === "bottom";
  const width = vertical ? size : along;
  const height = vertical ? along : size;
  const levelAt = (index: number) => {
    const step = edge === "top" || edge === "left" ? index : along - 1 - index;
    return step >= fade ? to : from + (to - from) * ((step + 0.5) / fade);
  };
  const tile: RampTile = {
    height,
    path: cellsPath(
      width,
      height,
      (x, y) =>
        levelAt(vertical ? y : x) >
        (thresholds[(y % size) * size + (x % size)] ?? 1)
    ),
    width,
  };
  rampCache.set(key, tile);
  return tile;
};

const svgUrl = (width: number, height: number, path: string) => {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" shape-rendering="crispEdges"><path d="${path}"/></svg>`;
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
};

const EDGE_POSITION = {
  bottom: "left bottom",
  left: "left top",
  right: "right top",
  top: "left top",
} as const satisfies Record<FillEdge, string>;

export interface FillStyleOptions {
  /** Colour, a palette name or any CSS colour. Default `ink`. */
  color?: DitherColor;
  /** Cell size: CSS pixels or any CSS length. Default `var(--dither-cell)`. */
  cell?: number | string;
  /** Gradient only: the dense side. Default `bottom`. */
  edge?: FillEdge;
  /** Gradient only: length of the fade in cells. Default 24. */
  length?: number;
  /** Gradient only: coverage at the edge. Default 1. */
  from?: number;
  /** Gradient only: coverage past the fade. Default 0.0625 (one cell in 16). */
  to?: number;
  /** Gradient only: threshold matrix. Default `bayer4`. */
  matrix?: DitherMatrix;
}

const times = (cell: number | string, count: number) =>
  typeof cell === "number" ? `${cell * count}px` : `calc(${cell} * ${count})`;

/**
 * Inline styles that paint an element with a fill variant: a background
 * colour and, for every variant but `solid`, a tiled CSS mask. The element
 * needs a size; children are masked too, so put content in a sibling.
 *
 * ```tsx
 * <div className="absolute inset-0" style={fillStyle("gradient", { color: "green", edge: "left" })} />
 * ```
 */
export const fillStyle = (
  variant: FillVariant,
  {
    color = "ink",
    cell = "var(--dither-cell)",
    edge = "bottom",
    length = 24,
    from = 1,
    to = 0.0625,
    matrix = "bayer4",
  }: FillStyleOptions = {}
): CSSProperties => {
  const backgroundColor = cssColor(color);
  if (variant === "solid") {
    return { backgroundColor };
  }
  if (variant === "dotted" || variant === "hatched") {
    const { size, path } = fillTile(variant);
    const image = svgUrl(size, size, path);
    const tile = times(cell, size);
    return {
      WebkitMaskImage: image,
      WebkitMaskSize: tile,
      backgroundColor,
      maskImage: image,
      maskSize: tile,
    };
  }
  // A ramp along the edge, unioned with the plain floor level. Bayer sets
  // nest, so the union is exact where both are anchored to the same edge.
  const ramp = ditherRamp({ edge, from, length, matrix, to });
  const { size } = getThresholdMap(matrix);
  const image = `${svgUrl(ramp.width, ramp.height, ramp.path)}, ${ditherMask(to, { matrix })}`;
  const size2 = `${times(cell, ramp.width)} ${times(cell, ramp.height)}, ${times(cell, size)}`;
  const repeat = `${edge === "top" || edge === "bottom" ? "repeat-x" : "repeat-y"}, repeat`;
  const position = `${EDGE_POSITION[edge]}, ${EDGE_POSITION[edge]}`;
  return {
    WebkitMaskImage: image,
    WebkitMaskPosition: position,
    WebkitMaskRepeat: repeat,
    WebkitMaskSize: size2,
    backgroundColor,
    maskImage: image,
    maskPosition: position,
    maskRepeat: repeat,
    maskSize: size2,
  };
};

/** Blur radius and strength of each bloom level. */
export const BLOOM_LEVELS = {
  high: { blur: 18, strength: 0.55 },
  low: { blur: 10, strength: 0.3 },
} as const satisfies Record<
  Exclude<Bloom, "off">,
  { blur: number; strength: number }
>;

/**
 * Styles for a bloom layer: a blurred, translucent copy of a fill drawn
 * behind it. `--dither-bloom` scales the strength per theme (1 in dark,
 * lower in light, where glows turn muddy). `undefined` when off.
 */
export const bloomLayerStyle = (bloom: Bloom): CSSProperties | undefined => {
  if (bloom === "off") {
    return undefined;
  }
  const { blur, strength } = BLOOM_LEVELS[bloom];
  return {
    filter: `blur(${blur}px)`,
    opacity: `calc(var(--dither-bloom, 1) * ${strength})`,
  };
};

/**
 * A CSS `filter` that glows around an element in `color`, for DOM pieces
 * (buttons, bars) where a copy of the fill is not handy. `undefined` when off.
 */
export const bloomFilter = (
  color: DitherColor,
  bloom: Bloom
): string | undefined => {
  if (bloom === "off") {
    return undefined;
  }
  const { blur, strength } = BLOOM_LEVELS[bloom];
  const tint = (share: number) =>
    `color-mix(in oklab, ${cssColor(color)} calc(var(--dither-bloom, 1) * ${Math.round(share * 100)}%), transparent)`;
  return `drop-shadow(0 0 ${Math.round(blur / 3)}px ${tint(strength * 1.4)}) drop-shadow(0 0 ${blur}px ${tint(strength)})`;
};

/** `{ filter }` for `bloomFilter`, ready to spread into `style`. */
export const bloomStyle = (color: DitherColor, bloom: Bloom): CSSProperties => {
  const filter = bloomFilter(color, bloom);
  return filter === undefined ? {} : { filter };
};

import type { ComponentProps } from "react";

import type { DitherMatrix } from "@/lib/dither/matrices";
import { DitherPattern } from "@/lib/dither/pattern";
import {
  bloomFilter,
  bloomLayerStyle,
  ditherRamp,
  fillTile,
} from "@/lib/dither/style";
import type { Bloom, FillEdge, FillVariant } from "@/lib/dither/style";
import { cssColor } from "@/lib/dither/tokens";
import type { DitherColor } from "@/lib/dither/tokens";

/**
 * SVG and DOM pieces of the style kit: a pattern for every fill variant
 * and two ways to draw bloom. Server-safe.
 */

/** Where a gradient fill's dense edge sits, in SVG user units. */
export interface FillRamp {
  /** The dense side. */
  edge: FillEdge;
  /** Coordinate of that side: y for `top`/`bottom`, x for `left`/`right`. */
  at: number;
  /** How far the fade runs from the edge. */
  length: number;
  /** How far the fill reaches past the edge in total. Default `length`. Past the fade it holds `floor`. */
  extent?: number;
}

export interface FillPatternProps {
  /** The id to reference, as in `fill="url(#id)"`. */
  id: string;
  /** The texture. */
  fill: FillVariant;
  /** Colour: a palette name or any CSS colour. Default `ink`. */
  color?: DitherColor;
  /** Cell size in SVG user units. Default 3. */
  cell?: number;
  /** Gradient only: coverage at the dense edge, 0 to 1. Default 1. */
  level?: number;
  /** Gradient only: coverage at the far end of the fade. Default 0.0625. */
  floor?: number;
  /** Gradient only: threshold matrix. Default `bayer4`. */
  matrix?: DitherMatrix;
  /** Gradient only: where the dense edge sits. Without it, a gradient fills one even `level`. */
  ramp?: FillRamp;
}

/**
 * An SVG `<pattern>` for any fill variant. Place it inside `<defs>` and
 * fill shapes with `url(#id)`. To reuse one ramp at several positions (one
 * per bar), reference it with `<pattern id="b2" href="#id" y={top} />`.
 */
export const FillPattern = ({
  id,
  fill,
  color = "ink",
  cell = 3,
  level = 1,
  floor = 0.0625,
  matrix = "bayer4",
  ramp,
}: FillPatternProps) => {
  const ink = { fill: cssColor(color) };
  if (fill === "solid") {
    return (
      <pattern id={id} width={cell} height={cell} patternUnits="userSpaceOnUse">
        <rect width={cell} height={cell} style={ink} />
      </pattern>
    );
  }
  if (fill === "dotted" || fill === "hatched") {
    const { size, path } = fillTile(fill);
    return (
      <pattern
        id={id}
        width={size * cell}
        height={size * cell}
        patternUnits="userSpaceOnUse"
        shapeRendering="crispEdges"
      >
        <path d={path} transform={`scale(${cell})`} style={ink} />
      </pattern>
    );
  }
  if (ramp === undefined) {
    return (
      <DitherPattern
        id={id}
        level={level}
        matrix={matrix}
        cell={cell}
        color={color}
      />
    );
  }
  const tile = ditherRamp({
    edge: ramp.edge,
    extent: (ramp.extent ?? ramp.length) / cell,
    from: level,
    length: ramp.length / cell,
    matrix,
    to: floor,
  });
  const width = tile.width * cell;
  const height = tile.height * cell;
  const origin = {
    bottom: { x: 0, y: ramp.at - height },
    left: { x: ramp.at, y: 0 },
    right: { x: ramp.at - width, y: 0 },
    top: { x: 0, y: ramp.at },
  }[ramp.edge];
  return (
    <pattern
      id={id}
      x={origin.x}
      y={origin.y}
      width={width}
      height={height}
      patternUnits="userSpaceOnUse"
      shapeRendering="crispEdges"
    >
      <path d={tile.path} transform={`scale(${cell})`} style={ink} />
    </pattern>
  );
};

export interface BloomGroupProps extends ComponentProps<"g"> {
  bloom: Bloom;
}

/**
 * An SVG group drawn as a glow: put solid copies of your shapes inside
 * and render it before (under) the real fills. Renders nothing when off.
 */
export const BloomGroup = ({ bloom, style, ...props }: BloomGroupProps) => {
  const layer = bloomLayerStyle(bloom);
  return layer === undefined ? null : (
    <g aria-hidden="true" {...props} style={{ ...layer, ...style }} />
  );
};

export type BloomBoxProps = ComponentProps<"div"> & {
  /** Glow colour: a palette name or any CSS colour. Default `ink`. */
  color?: DitherColor;
  bloom: Bloom;
};

/**
 * A wrapper that glows around whatever it holds, in `color`. A CSS
 * drop-shadow, so it follows dithered cells and transparent gaps.
 */
export const BloomBox = ({
  color = "ink",
  bloom,
  style,
  ...props
}: BloomBoxProps) => (
  <div {...props} style={{ filter: bloomFilter(color, bloom), ...style }} />
);

import { getThresholdMap } from "@/lib/dither/matrices";
import type { Rgba } from "@/lib/dither/tokens";

/**
 * CPU dithering for still images. Pure functions over RGBA pixels: the
 * input is never changed and the result is a new `ImageData`, so this runs
 * on the main thread or in a Web Worker (anywhere `ImageData` exists).
 */

export type OrderedMethod = "bayer4" | "bayer8" | "blue-noise";
export type DiffusionMethod = "floyd-steinberg" | "atkinson" | "sierra-lite";
export type DitherMethod = OrderedMethod | DiffusionMethod;

export const DITHER_METHODS = [
  "bayer4",
  "bayer8",
  "blue-noise",
  "floyd-steinberg",
  "atkinson",
  "sierra-lite",
] as const satisfies readonly DitherMethod[];

/** An RGB colour, each channel in [0, 1]. Alpha in an `Rgba` is ignored. */
export type PaletteColor = readonly [number, number, number] | Rgba;

/** At least two colours. Pixels map to the nearest one. */
export type ImagePalette = readonly [
  PaletteColor,
  PaletteColor,
  ...PaletteColor[],
];

/** Anything shaped like `ImageData`: RGBA bytes, row by row. */
export interface PixelBuffer {
  readonly data: Uint8ClampedArray;
  readonly width: number;
  readonly height: number;
}

interface SharedOptions {
  /** Output colours. Default black and white. */
  palette?: ImagePalette;
  /**
   * Brightness cut-off in [0, 1]. Lower values push more pixels towards
   * the lighter colours. Default 0.5.
   */
  threshold?: number;
}

/** Ordered dithering: stable between frames, a visible pattern. */
export interface OrderedOptions extends SharedOptions {
  method: OrderedMethod;
}

/** Error diffusion: finer detail on photos and logos. */
export interface DiffusionOptions extends SharedOptions {
  method: DiffusionMethod;
  /** Alternate the scan direction each row. Default `true`. */
  serpentine?: boolean;
}

export type DiffuseOptions = OrderedOptions | DiffusionOptions;

const BLACK_AND_WHITE: ImagePalette = [
  [0, 0, 0],
  [1, 1, 1],
];

// [dx, dy, weight] for each neighbour that receives part of the error.
type Kernel = readonly (readonly [number, number, number])[];

const KERNELS = {
  atkinson: [
    [1, 0, 1 / 8],
    [2, 0, 1 / 8],
    [-1, 1, 1 / 8],
    [0, 1, 1 / 8],
    [1, 1, 1 / 8],
    [0, 2, 1 / 8],
  ],
  "floyd-steinberg": [
    [1, 0, 7 / 16],
    [-1, 1, 3 / 16],
    [0, 1, 5 / 16],
    [1, 1, 1 / 16],
  ],
  "sierra-lite": [
    [1, 0, 2 / 4],
    [-1, 1, 1 / 4],
    [0, 1, 1 / 4],
  ],
} as const satisfies Record<DiffusionMethod, Kernel>;

const nearest = (palette: ImagePalette, r: number, g: number, b: number) => {
  let best = 0;
  let bestDistance = Infinity;
  for (let index = 0; index < palette.length; index += 1) {
    const color = palette[index];
    if (!color) {
      continue;
    }
    const dr = r - color[0];
    const dg = g - color[1];
    const db = b - color[2];
    // Weighted towards green, as the eye is.
    const distance = 0.3 * dr * dr + 0.59 * dg * dg + 0.11 * db * db;
    if (distance < bestDistance) {
      bestDistance = distance;
      best = index;
    }
  }
  return best;
};

const write = (
  out: Uint8ClampedArray,
  offset: number,
  color: PaletteColor,
  alpha: number
) => {
  out[offset] = color[0] * 255;
  out[offset + 1] = color[1] * 255;
  out[offset + 2] = color[2] * 255;
  out[offset + 3] = alpha;
};

const ditherOrdered = (
  image: PixelBuffer,
  method: OrderedMethod,
  palette: ImagePalette,
  bias: number
): Uint8ClampedArray<ArrayBuffer> => {
  const { data, width, height } = image;
  const out = new Uint8ClampedArray(data.length);
  const map = getThresholdMap(method);
  // Spread the threshold over one step between palette colours.
  const spread = 1 / (palette.length - 1);
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const offset = (y * width + x) * 4;
      const threshold =
        map.thresholds[(y % map.size) * map.size + (x % map.size)] ?? 0.5;
      const shift = (0.5 - threshold) * spread + bias;
      const r = (data[offset] ?? 0) / 255 + shift;
      const g = (data[offset + 1] ?? 0) / 255 + shift;
      const b = (data[offset + 2] ?? 0) / 255 + shift;
      const color = palette[nearest(palette, r, g, b)] ?? palette[0];
      write(out, offset, color, data[offset + 3] ?? 255);
    }
  }
  return out;
};

/** Pass one pixel's rounding error on to its unvisited neighbours. */
const spreadError = ({
  error,
  height,
  kernel,
  reverse,
  width,
  work,
  x,
  y,
}: {
  error: readonly [number, number, number];
  height: number;
  kernel: Kernel;
  reverse: boolean;
  width: number;
  work: Float32Array;
  x: number;
  y: number;
}) => {
  for (const [dx, dy, weight] of kernel) {
    const nx = reverse ? x - dx : x + dx;
    const ny = y + dy;
    if (nx < 0 || nx >= width || ny >= height) {
      continue;
    }
    const target = (ny * width + nx) * 3;
    for (let channel = 0; channel < 3; channel += 1) {
      work[target + channel] =
        (work[target + channel] ?? 0) + error[channel] * weight;
    }
  }
};

const ditherDiffusion = (
  image: PixelBuffer,
  kernel: Kernel,
  palette: ImagePalette,
  bias: number,
  serpentine: boolean
): Uint8ClampedArray<ArrayBuffer> => {
  const { data, width, height } = image;
  const out = new Uint8ClampedArray(data.length);
  const work = new Float32Array(width * height * 3);
  for (let index = 0; index < width * height; index += 1) {
    for (let channel = 0; channel < 3; channel += 1) {
      work[index * 3 + channel] = (data[index * 4 + channel] ?? 0) / 255 + bias;
    }
  }

  for (let y = 0; y < height; y += 1) {
    const reverse = serpentine && y % 2 === 1;
    for (let step = 0; step < width; step += 1) {
      const x = reverse ? width - 1 - step : step;
      const index = y * width + x;
      const r = work[index * 3] ?? 0;
      const g = work[index * 3 + 1] ?? 0;
      const b = work[index * 3 + 2] ?? 0;
      const color = palette[nearest(palette, r, g, b)] ?? palette[0];
      write(out, index * 4, color, data[index * 4 + 3] ?? 255);

      spreadError({
        error: [r - color[0], g - color[1], b - color[2]],
        height,
        kernel,
        reverse,
        width,
        work,
        x,
        y,
      });
    }
  }
  return out;
};

const DEFAULT_OPTIONS: DiffuseOptions = { method: "floyd-steinberg" };

/**
 * Dither an image to a palette. Returns a new `ImageData` the same size;
 * `image` is not modified. Default: Floyd–Steinberg in black and white.
 */
export const ditherImage = (
  image: PixelBuffer,
  options: DiffuseOptions = DEFAULT_OPTIONS
): ImageData => {
  const palette = options.palette ?? BLACK_AND_WHITE;
  const bias = 0.5 - (options.threshold ?? 0.5);
  let data: Uint8ClampedArray<ArrayBuffer>;
  switch (options.method) {
    case "bayer4":
    case "bayer8":
    case "blue-noise": {
      data = ditherOrdered(image, options.method, palette, bias);
      break;
    }
    case "floyd-steinberg":
    case "atkinson":
    case "sierra-lite": {
      data = ditherDiffusion(
        image,
        KERNELS[options.method],
        palette,
        bias,
        options.serpentine ?? true
      );
      break;
    }
    default: {
      const exhaustive: never = options;
      return exhaustive;
    }
  }
  return new ImageData(data, image.width, image.height);
};
